import useSuiLendInfoStore from '@/store/leverage/suiLendInfo'
import { useSdk } from '@cetus/sdk-factory'

export default function useGetSuiLendInfo() {
  const leverageSDK = useSdk('leverage')
  console.log('🚀🚀🚀 ~ useGetSuiLendInfo.ts:5 ~ useGetSuiLendInfo ~ leverageSDK:', leverageSDK)
  const { setAllLendingMarketData, setLstAprPercentMap } = useSuiLendInfoStore()
  const getSuiLendInfo = async () => {}
  const getLendingMarketData = async () => {
    const { allLendingMarketData, lstAprPercentMap } = await leverageSDK?.SuiLendModule.getLendingMarketData()
    console.log('🚀🚀🚀 ~ useGetSuiLendInfo.ts:11 ~ getLendingMarketData ~ lstAprPercentMap:', lstAprPercentMap)
    console.log('🚀🚀🚀 ~ useGetSuiLendInfo.ts:11 ~ getLendingMarketData ~ allLendingMarketData:', allLendingMarketData)
    if (allLendingMarketData) {
      setAllLendingMarketData(allLendingMarketData)
      setLstAprPercentMap(lstAprPercentMap)
    }
  }

  return { getSuiLendInfo, getLendingMarketData }
}
