import { create } from 'zustand'

interface SuiLendInfoState {
  allLendingMarketData: any
  lstAprPercentMap: any
  setAllLendingMarketData: (data: any) => void
  setLstAprPercentMap: (data: any) => void
}

const useSuiLendInfoStore = create<SuiLendInfoState>(set => ({
  allLendingMarketData: {},
  lstAprPercentMap: {},
  setAllLendingMarketData: (data: any) => set({ allLendingMarketData: data }),
  setLstAprPercentMap: (data: any) => set({ lstAprPercentMap: data })
}))

export default useSuiLendInfoStore
